import { test, expect } from '@playwright/test';

test.describe('Login Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
  });

  test('should display error message for invalid password', async ({ page }) => {
    await page.fill('#username', 'tomsmith');
    await page.fill('#password', 'wrongpassword');
    await page.click('button[type="submit"]');

    const errorMessage = await page.getByRole('alert');
    await expect(errorMessage).toContainText('Your password is invalid!');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/login');
  });

  test('should remain on login page after failed login attempt', async ({ page }) => {
    await page.fill('#username', 'tomsmith');
    await page.fill('#password', 'wrongpassword');
    await page.click('button[type="submit"]');

    const errorBanner = await page.locator('.flash.error');
    await expect(errorBanner).toBeVisible();
    await expect(errorBanner).toContainText('Your password is invalid!');
  });
});
